// HasWallet applies the HasEdge predicate on the "wallet" edge.
func HasWallet() predicate.ApiTokenTransaction {
	return predicate.ApiTokenTransaction(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, WalletTable, WalletColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasWalletWith applies the HasEdge predicate on the "wallet" edge with a given conditions (other predicates).
func HasWalletWith(preds ...predicate.ApiTokenWallet) predicate.ApiTokenTransaction {
	return predicate.ApiTokenTransaction(func(s *sql.Selector) {
		step := newWalletStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ApiTokenTransaction) predicate.ApiTokenTransaction {
	return predicate.ApiTokenTransaction(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ApiTokenTransaction) predicate.ApiTokenTransaction {
	return predicate.ApiTokenTransaction(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ApiTokenTransaction) predicate.ApiTokenTransaction {
	return predicate.ApiTokenTransaction(sql.NotPredicates(p))
}
